<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {get,write} from '../../../../packages/shared/src/client';import {useTask} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const route=useRoute(),task=useTask(),phone=ref(''),password=ref(''),code=ref(''),consent=ref(false),policy=ref<{version:string,url:string,notice:string,registrationEnabled:boolean,verificationDelivery:string}>(),cooldown=ref(0);
const recovery=route.path==='/recover-password';let timer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>task.run(async()=>{policy.value=await get('/public/accounts/privacy');}));onBeforeUnmount(()=>{if(timer)clearInterval(timer);password.value='';code.value='';});
async function send(){await task.run(async()=>{await write('/public/accounts/verification-codes','POST',{phone:phone.value,purpose:recovery?'RECOVER':'REGISTER'});task.message.value=policy.value?.verificationDelivery==='simulated'?'演示通知已受理，不会真实发送短信。':'验证码申请已受理，请等待短信；未送达时可稍后重试。';cooldown.value=60;timer=setInterval(()=>{if(--cooldown.value<=0&&timer)clearInterval(timer);},1000);});}
async function submit(){await task.run(async()=>{if(recovery)await write('/public/accounts/password-recovery','POST',{phone:phone.value,code:code.value,newPassword:password.value});else await write('/public/accounts/registration','POST',{phone:phone.value,code:code.value,password:password.value,consent:consent.value,policyVersion:policy.value?.version});password.value='';code.value='';task.message.value=recovery?'若验证信息与可用学生账户匹配，密码已更新，请重新登录。':'注册成功，请使用手机号与密码登录。';});}
</script>
<template><section class="card login"><h1>{{recovery?'找回学生账户密码':'注册学生账户'}}</h1><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><p v-if="policy&&!policy.registrationEnabled">当前尚未开放自助服务，请联系管理员。</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="手机号"><el-input v-model="phone" inputmode="tel" autocomplete="tel" maxlength="11"/></el-form-item><el-form-item label="短信验证码"><el-input v-model="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/><el-button :disabled="!/^1[3-9]\d{9}$/.test(phone)||cooldown>0||task.busy.value||!policy?.registrationEnabled" @click="send">{{cooldown>0?cooldown+'秒后重试':'申请验证码'}}</el-button></el-form-item><el-form-item label="密码（8至72字符，UTF-8最多72字节）"><el-input v-model="password" type="password" autocomplete="new-password" show-password maxlength="72"/></el-form-item><el-checkbox v-if="!recovery" v-model="consent">我已阅读并同意 <RouterLink to="/privacy">隐私规则</RouterLink>（{{policy?.version}}）</el-checkbox><p v-if="policy">{{policy.notice}}</p><el-button native-type="submit" type="primary" :disabled="task.busy.value||!policy?.registrationEnabled||!/^1[3-9]\d{9}$/.test(phone)||!/^\d{6}$/.test(code)||password.length<8||(!recovery&&!consent)">{{recovery?'更新密码':'验证并注册'}}</el-button></el-form><p><RouterLink to="/login">返回登录</RouterLink></p></section></template>
